-- ============ Part 2: rules, security (hand-written) ============

ALTER TABLE channels
  ADD CONSTRAINT channels_kind_check CHECK (kind IN ('PUBLIC', 'PRIVATE', 'GROUP', 'DM')),
  ADD CONSTRAINT channels_dm_key_check CHECK ((kind = 'DM') = (dm_key IS NOT NULL)),
  ADD CONSTRAINT channels_name_check CHECK (kind IN ('GROUP', 'DM') OR length(btrim(name)) >= 2);
CREATE UNIQUE INDEX channels_public_name ON channels (org_id, lower(name)) WHERE kind IN ('PUBLIC', 'PRIVATE') AND archived_at IS NULL;
ALTER TABLE channel_members
  ADD CONSTRAINT channel_members_role_check CHECK (role IN ('OWNER', 'MEMBER'));
ALTER TABLE messages
  ADD CONSTRAINT messages_body_check CHECK (length(body) <= 4000),
  ADD CONSTRAINT messages_content_check CHECK (length(btrim(body)) > 0 OR document_id IS NOT NULL OR deleted_at IS NOT NULL);
-- FR-MEET-012 message search (simple configuration: no stemming surprises across languages).
ALTER TABLE messages ADD COLUMN search tsvector GENERATED ALWAYS AS (to_tsvector('simple', CASE WHEN deleted_at IS NULL THEN body ELSE '' END)) STORED;
CREATE INDEX messages_search_idx ON messages USING gin (search);

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['channels', 'channel_members', 'messages'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;
GRANT SELECT, INSERT, UPDATE ON channels, messages TO hrvo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON channel_members TO hrvo_app;
-- Messages are soft-deleted (body cleared, deleted_at set); rows are never removed by the app.
REVOKE DELETE, TRUNCATE ON channels, messages FROM hrvo_app;

CREATE FUNCTION fn_chat_same_org() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_TABLE_NAME = 'channel_members' THEN
    IF NOT EXISTS (SELECT 1 FROM channels c WHERE c.id = NEW.channel_id AND c.org_id = NEW.org_id)
       OR NOT EXISTS (SELECT 1 FROM users u WHERE u.id = NEW.user_id AND u.org_id = NEW.org_id) THEN
      RAISE EXCEPTION 'channel member crosses organisations';
    END IF;
  ELSIF TG_TABLE_NAME = 'messages' THEN
    IF NOT EXISTS (SELECT 1 FROM channels c WHERE c.id = NEW.channel_id AND c.org_id = NEW.org_id) THEN
      RAISE EXCEPTION 'message channel belongs to another organisation';
    END IF;
    IF NEW.parent_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM messages p WHERE p.id = NEW.parent_id AND p.channel_id = NEW.channel_id AND p.parent_id IS NULL) THEN
        RAISE EXCEPTION 'a reply must answer a top-level message of the same channel';
      END IF;
    END IF;
    IF NEW.document_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM documents d WHERE d.id = NEW.document_id AND d.org_id = NEW.org_id) THEN
        RAISE EXCEPTION 'message document belongs to another organisation';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER channel_members_same_org BEFORE INSERT OR UPDATE ON channel_members FOR EACH ROW EXECUTE FUNCTION fn_chat_same_org();
CREATE TRIGGER messages_same_org BEFORE INSERT OR UPDATE ON messages FOR EACH ROW EXECUTE FUNCTION fn_chat_same_org();
